function garantirCriaturasTestePsi_(){
    const ids=new Set((criaturasDB||[]).map(x=>String(x.id)));
    for(const c of CRIATURAS_TESTE_PSI_)if(!ids.has(String(c.id)))criaturasDB.push(JSON.parse(JSON.stringify(c)));
}

