            esfera: String(bruto.esfera || '').trim(),
            arco: Math.max(1, Math.min(3, parseInt(bruto.arco) || 1)),
            custo: Math.max(0, parseNumero_(bruto.custo, 0)),
            observacao: String(bruto.observacao || bruto.descricao || '').trim(),
