        const w=Math.max(2*z,Number(o.larguraM||1)*ppm),h=Math.max(2*z,Number(o.alturaM||1)*ppm);
        const sel=String(o.id)===String(gmOficinaObjSel553_);
        // Sombra acompanha o zoom, sem mudar o valor salvo.
