    const ox=Number(f.x||0),oy=Number(f.y||0);
    const move=e=>{f.x=ox+(e.clientX-sx)/ppm;f.y=oy+(e.clientY-sy)/ppm;gm580Render_();};
    const up=()=>{window.removeEventListener('pointermove',move);gmOficinaPersistir_();};
