 return `<line x1="${x}" y1="${y}" x2="${x2}" y2="${y2}" stroke="${e.stroke}" stroke-opacity="${e.strokeOpacity??1}" stroke-width="${sw}" stroke-linecap="round" ${dash?`stroke-dasharray="${dash}"`:''}/>`;
