   for(const q of a){const gx=Math.floor(q.x),gy=Math.floor(q.y),k=gx+','+gy;if(cells.has(k))continue;cells.add(k);out.push(`<rect x="${gx*p}" y="${gy*p}" width="${p}" height="${p}" fill="${e.stroke}" fill-opacity="${op}"/>`);}
